// Parity with Sahaj's Python twin (contracts/oracle_test_cases.json, generated by
// pipeline/sim/make_oracle_cases.py). Gate G04: relative tolerance 1e-5.
import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { metabolicPower, minettiCost, o2RateGph, speed } from "../engine/physiology";
import { computeEnvelope } from "../engine/envelope";

const oracle = JSON.parse(readFileSync(new URL("../../../contracts/oracle_test_cases.json", import.meta.url), "utf8"));
const A = oracle.assumptionsDefault;
const rel = (a: number, b: number) => Math.abs(a - b) / Math.max(1e-12, Math.abs(b));
const TOL = oracle.tolerance.relative;

describe("oracle: walking model", () => {
  for (const c of oracle.walking.filter((w: { grade?: number }) => w.grade === undefined)) {
    it(`conversion check: ${c.metabolicW} W`, () => expect(rel(o2RateGph(c.metabolicW), c.o2GPerH)).toBeLessThan(TOL));
  }
  for (const c of oracle.walking.filter((w: { grade?: number }) => w.grade !== undefined)) {
    it(`grade ${c.grade}`, () => {
      const v = speed(c.grade, A.v0, A.fMob);
      expect(rel(v, c.speed)).toBeLessThan(TOL);
      expect(rel(minettiCost(c.grade), c.costOfWalking)).toBeLessThan(TOL);
      const M = metabolicPower(c.grade, v, A.bodyMassKg, A.loadKg, A.kG, A.mRestW, A.etaSubstrate);
      expect(rel(M, c.metabolicW)).toBeLessThan(TOL);
      expect(rel(o2RateGph(M), c.o2GPerH)).toBeLessThan(TOL);
    });
  }
});

describe("oracle: envelope grids", () => {
  for (const c of oracle.envelope) {
    it(c.name, () => {
      const rows = c.z.length, cols = c.z[0].length;
      const h = Float32Array.from(c.z.flat());
      const s = Float32Array.from(c.blocked.flat().map((b: boolean) => (b ? 90 : 0)));
      const a = c.assumptions;
      const out = computeEnvelope(h, s, {
        cols, rows, cellM: c.cellM, slopeLimitDeg: a.slopeLimitDeg, v0: a.v0, kG: a.kG, mRestW: a.mRestW, bodyMassKg: a.bodyMassKg,
        reserveM: a.reserveM, timeBudgetS: c.budgetTimeS, timeSpentS: 0,
        crew: [
          { fMob: a.fMob, loadKg: a.loadKg, o2BudgetG: c.budgetO2G, o2SpentG: 0 },
          { fMob: a.fMob, loadKg: a.loadKg, o2BudgetG: c.budgetO2G, o2SpentG: 0 },
        ],
        havens: [[c.haven[1], c.haven[0]]],
      });
      const exp = c.expect.timeToHaven as (number | null)[][];
      for (let r = 0; r < rows; r++) for (let k = 0; k < cols; k++) {
        const e = exp[r][k], g = out.timeToHaven[r * cols + k];
        if (e === null || !Number.isFinite(e)) expect(Number.isFinite(g)).toBe(false);
        else expect(rel(g, e)).toBeLessThan(TOL);
      }
    });
  }
});

import { mars24 } from "../engine/mars24";
describe("oracle: Mars24 (GISS worked examples)", () => {
  for (const c of oracle.mars24) {
    it(c.label, () => {
      const r = mars24(Date.parse(c.utc), c.lonEastDeg, c.latDeg, c.ttMinusUtcS);
      const e = c.expect;
      expect(Math.abs(r.MSD - e.MSD)).toBeLessThan(1e-6);
      expect(Math.abs(r.Ls - e.Ls)).toBeLessThan(1e-4);
      expect(Math.abs(r.EOT_deg - e.EOT_deg)).toBeLessThan(1e-4);
      expect(Math.abs(r.MST_h - e.MST_h)).toBeLessThan(1e-5);
      expect(Math.abs(r.LMST_h - e.LMST_h)).toBeLessThan(1e-5);
      expect(Math.abs(r.LTST_h - e.LTST_h)).toBeLessThan(1e-5);
      expect(Math.abs(r.declination - e.declination)).toBeLessThan(1e-4);
      expect(Math.abs(r.zenith - e.zenith)).toBeLessThan(1e-3);
      expect(Math.abs(r.azimuth - e.azimuth)).toBeLessThan(1e-3);
    });
  }
});
